package ui

import (
	"time"

	"github.com/egoist/mygo/ui"
)

// Easing and duration are shared by every motion in the app. Only colour
// changes are animated; MyGo keeps colour transitions under reduced motion.
var (
	Ease = ui.CubicBezier(0.22, 1, 0.36, 1)
	Fade = ui.ElementTransition{
		Duration: 180 * time.Millisecond,
		Ease:     Ease,
		Colors:   true,
	}
)

// Tokens are the single source of truth for surface, text, and accent colors.
// Values are tuned per appearance rather than generated by inversion.
type Tokens struct {
	App        ui.Color
	Sidebar    ui.Color
	Surface    ui.Color
	SurfaceAlt ui.Color
	Border     ui.Color
	BorderSoft ui.Color
	Text       ui.Color
	Muted      ui.Color
	Faint      ui.Color
	Accent     ui.Color
	AccentText ui.Color
	AccentSoft ui.Color
	Danger     ui.Color
	Warning    ui.Color
	Success    ui.Color
	Focus      ui.Color
	Shadow     ui.Color
}

// NewTokens derives a palette from the system theme. Dark mode uses its own
// elevation steps and softer accent instead of inverted light-mode colors.
func NewTokens(base *ui.Theme, prefersDark bool) Tokens {
	if prefersDark {
		return Tokens{
			App:        ui.Hex("#191a1c"),
			Sidebar:    ui.Hex("#1f2023"),
			Surface:    ui.Hex("#25272b"),
			SurfaceAlt: ui.Hex("#2c2e33"),
			Border:     ui.Hex("#3a3d43"),
			BorderSoft: ui.Hex("#303237"),
			Text:       ui.Hex("#f2f2f3"),
			Muted:      ui.Hex("#a8acb3"),
			Faint:      ui.Hex("#7d828b"),
			Accent:     ui.Hex("#7fb1e8"),
			AccentText: ui.Hex("#101820"),
			AccentSoft: ui.Hex("#26384c"),
			Danger:     ui.Hex("#e78a8a"),
			Warning:    ui.Hex("#d4ab6a"),
			Success:    ui.Hex("#8dc7a9"),
			Focus:      ui.Hex("#9cc7f5"),
			Shadow:     ui.RGBA(0, 0, 0, 0.36),
		}
	}
	return Tokens{
		App:        ui.Hex("#f7f7f5"),
		Sidebar:    ui.Hex("#f1f1ee"),
		Surface:    ui.Hex("#ffffff"),
		SurfaceAlt: ui.Hex("#f5f5f3"),
		Border:     ui.Hex("#d9d9d4"),
		BorderSoft: ui.Hex("#e8e8e4"),
		Text:       ui.Hex("#1f2023"),
		Muted:      ui.Hex("#666970"),
		Faint:      ui.Hex("#8b8e95"),
		Accent:     ui.Hex("#2f6699"),
		AccentText: ui.Hex("#ffffff"),
		AccentSoft: ui.Hex("#e7f0f8"),
		Danger:     ui.Hex("#a94b4b"),
		Warning:    ui.Hex("#956c2e"),
		Success:    ui.Hex("#397a5b"),
		Focus:      ui.Hex("#2f6699"),
		Shadow:     ui.RGBA(28, 30, 33, 0.12),
	}
}

// Space maps to the app's 4px baseline grid.
func Space(n float32) float32 { return 4 * n }

// State is one of the eight defined interactive states.
type State uint8

const (
	Default State = iota
	Hover
	Focus
	Active
	Disabled
	Loading
	Error
	Success
)

// ControlFace describes the visual treatment of an interactive element.
type ControlFace struct {
	Background ui.Color
	Border     ui.Color
	Text       ui.Color
}

// Face returns the token-driven appearance for one control state.
// "Quiet" controls (toolbar, sidebar rows) stay neutral except for focus and
// the active selection, while primary controls reserve the accent color.
func (t Tokens) Face(state State, primary, quiet bool) ControlFace {
	switch {
	case state == Disabled:
		return ControlFace{t.SurfaceAlt, t.BorderSoft, t.Faint}
	case state == Loading:
		return ControlFace{t.SurfaceAlt, t.Border, t.Muted}
	case state == Error:
		return ControlFace{t.SurfaceAlt, t.Danger.Alpha(0.45), t.Danger}
	case state == Success:
		return ControlFace{t.SurfaceAlt, t.Success.Alpha(0.45), t.Success}
	case state == Focus:
		f := ControlFace{t.Surface, t.Focus, t.Text}
		if primary {
			f.Background, f.Border, f.Text = t.Accent, t.Focus, t.AccentText
		}
		return f
	case state == Active:
		if primary {
			return ControlFace{t.Accent.Mix(t.Text, 0.12), t.Accent, t.AccentText}
		}
		if quiet {
			return ControlFace{t.AccentSoft, t.AccentSoft, t.Accent}
		}
		return ControlFace{t.AccentSoft, t.Accent, t.Accent}
	case state == Hover:
		if primary {
			return ControlFace{t.Accent.Mix(t.Surface, 0.12), t.Accent, t.AccentText}
		}
		return ControlFace{t.SurfaceAlt, t.Border, t.Text}
	default:
		if primary {
			return ControlFace{t.Accent, t.Accent, t.AccentText}
		}
		if quiet {
			return ControlFace{t.Sidebar, t.Sidebar, t.Text}
		}
		return ControlFace{t.Surface, t.Border, t.Text}
	}
}
